@Injectable()
export class DenyByDefaultGuard implements CanActivate {
  constructor(private reflector: Reflector, private policy: Policy) {}
  async canActivate(ctx: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC, [
      ctx.getHandler(), ctx.getClass(),
    ]);
    if (isPublic) return true;                       // explicit, reviewable opt-out
    const req = ctx.switchToHttp().getRequest();
    return (await this.policy.decide(req)).allowed;  // true only with an explicit grant
  }
}
